#!/usr/bin/env python3
"""Regenerate the public Awesome README from the canonical structured records."""
import json, pathlib, re, collections, datetime
ROOT=pathlib.Path(__file__).resolve().parents[1]
meta=json.loads((ROOT/'data/meta.json').read_text())
cutoff=meta['reviewed'];human=datetime.date.fromisoformat(cutoff).strftime('%d %B %Y').lstrip('0')
works=json.loads((ROOT/'data/works.json').read_text())
media=json.loads((ROOT/'data/media.json').read_text())
CATS={
 'benchmark':[('tactile-benchmarks','Visuo-Tactile Benchmarks'),('precision-assembly','Precision and Assembly'),('dexterous-benchmarks','Dexterous Manipulation'),('general-manipulation','General Manipulation'),('robustness-evaluation','Robustness and Evaluation'),('supporting-resources','Supporting Tools and Data')],
 'policy':[('tactile-il','Visuo-Tactile Policy Learning'),('tactile-foundation','Tactile VLA and World-Action Models'),('rgbd-3d','RGB-D and 3D Policies'),('visual-precision-rl','Visual Precision and Reinforcement Learning'),('generalist-foundation','Generalist Policy Foundations')]}
BENCH=[('simulator','Simulator'),('simulatorVersion','Simulator version and scope'),('taskCount','Task count and scope'),('taskListScope','Task-list scope'),('capabilities','Capability dimensions'),('metrics','Metrics'),('robots','Robots'),('sensors','Sensors and observations'),('data','Demonstrations and data'),('protocol','Evaluation protocol'),('baselines','Evaluated baselines')]
POLICY=[('family','Policy family'),('baseModel','Base model and architecture'),('modelSize','Model size and component'),('inputs','Deployment inputs'),('outputs','Action outputs and horizon'),('trainingMethod','Training method'),('trainingData','Training data'),('trainingTime','Training duration'),('trainingHardware','Training hardware'),('controlRate','Inference and control rates'),('evaluation','Evaluation scope')]
def text(v):return ' · '.join(map(str,v)) if isinstance(v,list) else str(v if v not in ['',None] else 'Not reported')
def clean(v):return text(v).replace('|','\\|').replace('\n',' ').replace('<','&lt;').replace('>','&gt;')
def name(w,c):return w.get(c+'Name',w['name'])
def release(w,c):return w.get('releaseByCollection',{}).get(c,w['release'])
def link(w):return w['links'].get('paper') or w['links'].get('project') or w['evidence'][0]['url']
def ordered(items):return sorted(items,key=lambda w:(w.get('date',''),w['name']),reverse=True)
def sources(w,key):
 e=[(i+1,s)for i,s in enumerate(w['evidence'])if any(key==f or key.startswith(f+'.') or f==key.split('.')[0] for f in s.get('fields',[]))]
 return ' '+''.join(f'[{i}]({s["url"]}) 'for i,s in e[:3]) if e else ''
bench=[w for w in works if 'benchmark'in w['collections']and'supporting-resources'not in w['categories']]
policies=[w for w in works if 'policy'in w['collections']]
support=[w for w in works if 'supporting-resources'in w['categories']]
lines=['<!-- Generated by scripts/generate.py from data/works.json. Edit the structured source, not this generated index. -->',
 '<h1 align="center">Awesome RGBDT Manipulation</h1>',
 '<p align="center"><strong>Benchmarks and policies for precise, contact-rich robot manipulation.</strong></p>',
 '<p align="center">RGB · Depth · Tactile · Force feedback</p>',
 '<p align="center"><a href="#benchmarks">Benchmarks</a> · <a href="#policies">Policies</a> · <a href="data/works.json">Structured catalog</a> · <a href="METHODOLOGY.md">Curation</a> · <a href="website/README.md">Local website</a></p>',
 '',f'Reviewed through **{human}**. **{len(works)} unique research records**, including **{len(bench)} benchmark records**, **{len(policies)} policy records**, and **{len(support)} supporting resources**. A work can contribute to both main collections, so counts cannot be added.','',
 '## About','',
 'This reference connects evaluation suites with the policies used for precision, dexterity and contact-rich manipulation. Benchmark records retain task names, task-count scope, simulator versions, physical sensors, demonstrations and evaluation protocols. Policy records retain architectures, actual deployment observations, action outputs, model sizes, training data, hardware, duration and reported control rates.','',
 '- Primary papers, official projects, repositories and model cards support the records.','- Measured depth, inferred geometry, tactile arrays, tactile images, wrist force/torque and privileged training labels are distinct.','- Paper experiments, current code, released datasets and model checkpoints retain their own version and availability scope.','- **Not reported** means the inspected sources do not disclose a value; **Not verified** marks an unresolved value. Neither is zero or proof of absence.','- Figures retain author credit and original rights; repository licensing does not relicense research figures.','',
 '## Start here','',
 '- **Visuo-tactile evaluation:** OpenViTac, UniVTAC, ManiFeel, Tac-Bench, ContactWorld and the TacBench evaluation introduced with Sparsh.','- **Precision and assembly:** Peg-in-Bench, ManipulationNet, FMB, Factory, IndustReal, AutoMate and LABIT.','- **Touch-conditioned policies:** 3D-ViTac, Reactive Diffusion Policy, VT-Refine, FTP-1, OpenVTLA, PACE and recent tactile VLA / world-action policies.','- **Visual and 3D foundations:** Diffusion Policy, ACT, DP3, PerAct, RVT-2, HIL-SERL, DPPO and selected generalist VLA / world-action models.','',
 '## Contents','',
 '- [Benchmarks](#benchmarks)']
for key,label in CATS['benchmark']:lines.append(f'  - [{label}](#{key})')
lines+=['- [Policies](#policies)']
for key,label in CATS['policy']:lines.append(f'  - [{label}](#{key})')
lines+=['- [Local preview and updates](#local-preview-and-updates)','- [Attribution](#attribution)','']
for c,heading in [('benchmark','Benchmarks'),('policy','Policies')]:
 lines+=['## '+heading,'']
 lines+=['Categories are overlapping discovery routes. Each record has one primary placement in this README; the website exposes all applicable categories.','']
 placed=set()
 for cat,label in CATS[c]:
  items=ordered([w for w in works if c in w['collections']and cat in w['categories']and w['id']not in placed and (cat=='supporting-resources' or 'supporting-resources'not in w['categories'])])
  lines += [f'<a id="{cat}"></a>',f'### {label}','']
  if not items:lines+=['See related records in the interactive catalog.',''];continue
  cols=['Date','Work','Setting','Tasks / simulator' if c=='benchmark'else'Architecture / inputs','Release','Primary links']
  lines+=['| '+' | '.join(cols)+' |','| :-- | :-- | :-- | :-- | :-- | :-- |']
  for w in items:
   obj=w.get(c,{})
   info=(text(obj.get('taskCount'))+'; '+text(obj.get('simulator')))if c=='benchmark'else(text(obj.get('family'))+'; '+text(obj.get('inputs')))
   if len(info)>190:info=info[:187].rstrip()+'…'
   links=' · '.join(f'[{k.title()}]({u})'for k,u in w['links'].items()if u)
   lines.append('| '+' | '.join([w['date']or'Undated',f'[{clean(name(w,c))}](#record-{c}-{w["id"]})',clean(w['environments']),clean(info),clean(release(w,c).get('code')),links+f' <!-- work:{w["id"]} -->'])+' |')
  lines+=['']
  for w in items:
   placed.add(w['id']);obj=w.get(c,{})
   lines += [f'<a id="record-{c}-{w["id"]}"></a>','<details>',f'<summary><strong>{clean(name(w,c))}</strong> — {clean(w["title"])}</summary>','',f'**{w["date"]or"Undated"} · {clean(w["venue"])} · {clean(w["institution"])}**','',clean(w.get(c+'Summary',w['summary'])),'']
   f=media.get(w['id'],{}).get(c)
   if f:lines += [f'<img src="website/public{f["path"]}" width="760" alt="{clean(f["alt"])}"/>','',f'*{clean(f["credit"])} · [Figure source]({f["page"]}) · Original rights retained.*','']
   lines+=['| Field | Reported value and source scope |','| :-- | :-- |']
   for k,l in (BENCH if c=='benchmark'else POLICY):lines.append(f'| {l} | {clean(obj.get(k,"Not reported"))}{sources(w,c+"."+k)} |')
   for k,l in [('modalities','Observations / modalities'),('environments','Evaluation domain'),('embodiments','Embodiment')]:lines.append(f'| {l} | {clean(w[k])} |')
   for k,v in release(w,c).items():lines.append(f'| Release: {clean(k)} | {clean(v)}{sources(w,"release."+k)} |')
   if c=='benchmark':
    tasks=obj.get('tasks',[])
    lines+=['',f'**Task names — {clean(obj.get("taskListScope","Not reported"))}:**','']
    lines += ['- '+clean(t)for t in tasks] if tasks else ['Task names not reported or not verified in the cited sources.']
   if w.get('caveats'):lines+=['','**Scope and qualifications**','']+['- '+clean(x)for x in w['caveats']]
   lines+=['','**Primary evidence**','']+[f'{i}. [{clean(s["label"])}]({s["url"]})'+(' — '+clean(s['note'])if s.get('note')else'')for i,s in enumerate(w['evidence'],1)]
   lines+=['','</details>','']
lines+=['## Local preview and updates','',
 '```sh','cd website','npm ci','npm run dev -- --host 127.0.0.1 --port 4345','```','',
 'Open <http://127.0.0.1:4345>. The site supports task-aware search, collection-specific facets, saved records, deep links, source evidence, figure enlargement, comparison and filtered CSV export.','',
 'The canonical source is [`data/works.json`](data/works.json), with collection-specific figure provenance in [`data/media.json`](data/media.json). Regenerate and validate after an edit:','',
 '```sh','python3 scripts/generate.py','python3 scripts/validate.py','cd website','npm test','npm run check','npm run build','```','',
 'See [CONTRIBUTING.md](CONTRIBUTING.md) for the evidence workflow and [COVERAGE.md](COVERAGE.md) for coverage boundaries. This is a reviewed snapshot, not an automatic live feed. Candidate discovery is kept separate from reviewed publication.','',
 '## Attribution','',
 'Thanks to the authors and maintainers of the linked papers, benchmarks, policies, simulators and datasets. Research figures remain the property of their authors and publishers. Original repository code and prose are licensed under MIT; linked artifacts retain their own licenses. The visual interface adapts the local Awesome-Ego-Robotics / Awesome-UMI atlas design.','']
readme='\n'.join(lines)
(ROOT/'README.md').write_text(readme)
(ROOT/'website/public/README.md').write_text(readme)
# Public audit summary: descriptive scope only, never private project recommendations.
counts=collections.Counter(x for w in works for x in w['categories'])
coverage=['# Coverage and evidence boundary','',f'Review cutoff: {cutoff}. {len(works)} unique records; {len(bench)} benchmark records; {len(policies)} policy records; {len(support)} supporting resources. Collection and category counts overlap.','',
 '## Search areas','']
for c in CATS:
 for key,label in CATS[c]:coverage.append(f'- {label}: {counts[key]} records with this classification.')
coverage+=['','## Evidence methodology','','Search recent and foundational work independently across benchmark and policy families. Follow public citation chains, official task registries, repository installation instructions, release branches, model cards, appendices and actual license files. Cross-review simulator versions, real-vs-simulation claims, task scope, deployed sensing and resource accounting.','',
 '## Explicit boundaries','','Standalone sensor hardware, representation-only pretraining, medical palpation, locomotion, haptics and generic depth-estimation literature are not exhaustively indexed. Selected supporting resources contextualize manipulation work.','',
 'Task labels can refer to distinct suites, released registries, evaluated subsets or examples. They are never pooled into a global count of independent tasks. A paper can introduce both a benchmark and a policy without becoming two unique paper records.','',
 'Training cost and component sizes are often undisclosed. Not reported and Not verified remain visible. No missing value is estimated from another implementation.','',
 '## Figures','','Main benchmark figures show task sets, capability taxonomies or physical evaluation setups. Main policy figures show architecture, learning/control pipelines or the author system diagram. Figure provenance is stored in data/media.json.','',
 '## Maintenance','','Edit the structured source, retain field evidence and scope, regenerate README, run data/build/browser checks, then review the resulting diff. scripts/discover.py can retrieve candidate papers from the official arXiv API; it never adds unreviewed results to the public catalog.','']
(ROOT/'COVERAGE.md').write_text('\n'.join(coverage))
print(json.dumps({'uniqueRecords':len(works),'benchmarks':len(bench),'policies':len(policies),'supporting':len(support),'readmeLines':len(lines),'readmeBytes':len(readme.encode())},indent=2))

seen=set();watch=[]
for w in works:
 for key in ['project','code']:
  u=w['links'].get(key)
  if u and u not in seen:watch.append({'work':w['id'],'kind':key,'url':u});seen.add(u)
(ROOT/'data/watchlist.json').write_text(json.dumps({'purpose':'Official sources for future reviewed updates; no automatic publishing','reviewed':cutoff,'sources':watch},indent=2)+'\n')
